import{_ as s}from"./chunks/05-terminal.BgHtxeE4.js";import{_ as i,a as t}from"./chunks/05d-terminal-session.B-dA9tke.js";import{_ as e,o as n,c as l,a2 as r}from"./chunks/framework.DUZafPzB.js";const b=JSON.parse('{"title":"远程终端 Terminal","description":"","frontmatter":{},"headers":[],"relativePath":"zh/features/terminal.md","filePath":"zh/features/terminal.md","lastUpdated":null}'),o={name:"zh/features/terminal.md"};function h(p,a,g,d,c,k){return n(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="远程终端-terminal" tabindex="-1">远程终端 Terminal <a class="header-anchor" href="#远程终端-terminal" aria-label="Permalink to &quot;远程终端 Terminal&quot;">​</a></h1><p>可选功能：在浏览器里开 Agent 本机的交互式 shell。<strong>未沙箱</strong>——能做该 OS 用户能做的一切。务必只在可信环境启用。</p><p><img src="'+s+'" alt="Terminal：等待 TOTP"></p><p><img src="'+i+'" alt="输入 6 位验证码"></p><p><img src="'+t+`" alt="已打开会话并执行命令"></p><h2 id="启用-2fa-agent-本机" tabindex="-1">启用 2FA（Agent 本机） <a class="header-anchor" href="#启用-2fa-agent-本机" aria-label="Permalink to &quot;启用 2FA（Agent 本机）&quot;">​</a></h2><p>密钥只存在 Agent 上；Hub <strong>只转发</strong>验证码做本地校验，从不保存 TOTP 密钥。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./agent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --setup-terminal-2fa</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 或指定配置：</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./agent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --setup-terminal-2fa</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/agent.toml</span></span></code></pre></div><p>按向导把密钥写入 Authenticator 后，<strong>重启 Agent</strong>。</p><p>也可用环境变量（适合自动化；环境变量优先；无效值会导致启动失败，不会静默降级）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> FILEBOX_AGENT_TERMINAL_TOTP_SECRET</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;BASE32SECRET……&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # ≥16 字节解码后</span></span></code></pre></div><h2 id="打开-恢复会话" tabindex="-1">打开 / 恢复会话 <a class="header-anchor" href="#打开-恢复会话" aria-label="Permalink to &quot;打开 / 恢复会话&quot;">​</a></h2><ol><li>侧栏 <strong>Terminal</strong>。</li><li>输入当前 6 位 TOTP → <strong>Open terminal</strong>（或 Resume）。</li><li>每次打开 / 恢复都要<strong>新的</strong>验证码；用过的码会被拒绝，等下一个 30s 窗口。</li><li><strong>Sessions</strong> 可 Refresh、Resume、End。</li><li><strong>New session</strong> 再开一个 shell。</li></ol><h2 id="会话生命周期" tabindex="-1">会话生命周期 <a class="header-anchor" href="#会话生命周期" aria-label="Permalink to &quot;会话生命周期&quot;">​</a></h2><ul><li>浏览导航、断线、Hub 重启、空闲后 shell 仍可 <strong>Resume</strong>。</li><li>Agent <strong>进程重启</strong>会丢失会话；回放最近约 <strong>256 KiB</strong> 输出。</li><li>登出浏览器会断开附着，但 shell 可继续跑，直到 End 或 Agent 重启。</li></ul><h2 id="安全提醒" tabindex="-1">安全提醒 <a class="header-anchor" href="#安全提醒" aria-label="Permalink to &quot;安全提醒&quot;">​</a></h2><ul><li>终端能力等于该 Agent 的 OS 用户权限。</li><li>不要在共享或不信任的机器上启用。</li><li>Hub / Agent / 前端大版本建议一起升（见 release notes）。</li></ul><p>相关：<a href="./security">安全与敏感文件</a> · <a href="/filebox/zh/ops/agent">Agent 运维</a></p>`,18)])])}const f=e(o,[["render",h]]);export{b as __pageData,f as default};
